// Step 1 (shell): create the module
//   mkdir app && cd app
//   go mod init github.com/acme/app
//
// Step 2: write code that imports an external package
// file: main.go
package main

import (
	"fmt"

	"github.com/google/uuid" // third-party module
)

func main() {
	id := uuid.New() // generate a random UUID v4
	fmt.Println("new id:", id.String())
}

// Step 3 (shell): fetch the dependency and sync go.mod/go.sum
//   go mod tidy
// Step 4: run it
//   go run .

// module: github.com/acme/app  (go.mod at repo root)

// file: pricing/pricing.go
package pricing // package name = directory name by convention

// taxRate is unexported (lowercase) -> visible only inside this package.
const taxRate = 0.08

// WithTax is exported (uppercase) -> usable by other packages.
func WithTax(amount float64) float64 {
	return amount * (1 + taxRate)
}

// file: main.go
package main

import (
	"fmt"

	"github.com/acme/app/pricing" // import path = module path + dir
)

func main() {
	// We can call WithTax (exported) but not taxRate (unexported).
	fmt.Printf("total: %.2f\n", pricing.WithTax(100))
}
